/* generat de tools/i18n25/hub-i18n.mjs din data/hub-i18n/apps/rue.json — nu edita de mână */
__hubApps("rue",{"FreeDetect":{"line":"Хочете перевірити, чі текст выглядать як написаный ШІ або скопірованый? Ту є 42 зовнішніх інштрументы і ґенератор цітат на єдным місці. Додаток сам ничого не выявляє.","detail":"Панель 42 зовнішніх інштрументів на выявлїня ШІ/плаґіату і ґенератор цітат (перевіряє ISBN). Сам ничого локално не выявлять; помагать при перевірці жерел.","tags":["каталог","цітаты"]},"Arhiva-fara-frontiere":{"line":"Проглядайте колекції Internet Archive без конта: пошук, сторінкы матеріалів, попереднє проглядіня і збераня выбраного. Неофіціалне; archive.org бачіть ваш IP і пошукы.","detail":"Неофіціалный переглядач колекцій Internet Archive (пошук, сторінкы матеріалів, попереднє проглядіня, облюблены і недавны пошукы зберіганы локално), без конта. Не шукать у Wayback Machine; archive.org достає ваш IP і пошукы.","tags":["веб-архівы","жерела"]},"AcademiSearch":{"line":"Шукайте раз і видьте наукові праці з десятків отвореных жерел. Список можете зберегти для цітованя. Треба інтернет; ваши пошукы ідуть до тых сервісів.","detail":"Академічный мета-пошук по 11 отвореных API (OpenAlex, Crossref, arXiv і інші) з посиланями на портали; експорт BibTeX/RIS/CSV. Треба інтернет; ваши запыты ідуть до тых сервісів.","tags":["література","жерела"]},"Surveyor":{"line":"Які посиланя є на вашім сайті і котры з них зломлены? Выпише їх з якорями і переадресаціями. Зовнішні не годно надійно підтвердити. Лем для ваших властных сайтів.","detail":"Зводить перелік посилань сайту (статічный HTML, інтерфейс по анґліцькы), включно з якорями і переадресаціями. Зовнішні посиланя не годно підтвердити з проглядача (CORS); посылать запыты; перевіряйте лем свої сайты.","tags":["мертвы посиланя","аудіт"]},"Trade-Free-Link-Guardian":{"line":"Для вашого сайту на WordPress: находить зломлены посиланя і справлять їх, без зовнішнєго сервісу. Міняє властный зміст, тому наперед зробте резервну копію. Не тестованый на справжнім WordPress.","detail":"Плаґін для WordPress, котрый перевіряє посиланя і детерміновано справлять зломлены, без зовнішнёго сервісу. Міняє справжній зміст: зробте резервну копію. Не тестованый на справжнім WordPress.","tags":["WordPress","GPL v2"]},"OUTPOST":{"line":"Слідуйте за своіма сайтами і видьте, чі ся ще одзывають. Робить лем, покы карта остає отворена. Сторінка з помылков все єден ся рахує за одповідь. Інтерфейс є по анґліцькы.","detail":"Монітор досяжности в проглядачі: перевіряє, чі ваши сайты одзывають ся (не читать HTTP-статус; 404/500 ся рахують за одповідь). Лем покы є отворена вкладка. Інтерфейс по анґліцькы.","tags":["моніторінг"]},"ScryVeil":{"line":"Зробте перевірку безпеки домены і достаньте текстовый звіт на збераня. Дакотры перевіркы можуть браковати або требовати ключ. Звертать ся до сервісів третіх сторін; лем властны домены.","detail":"Діаґностика безпеки домены (DNS, RDAP, сертіфікаты) з текстовым звітом на експорт; перевіркы заголовків і репутації часто блокуют або требують ключ. Звертать ся до третіх сторін; лем для своіх домен.","tags":["OSINT","безпека"]},"Vitrina":{"line":"Вставте публічный пост з Facebook на свій сайт без конта і скопіруйте готовый код. Неофіціалне; Meta бачіть ваш IP, а одображіня не є ґарантованé.","detail":"Вбудовує публічны сторінкы/пости Facebook через плаґіны Meta, неофіціално; копіруе код вбудованя. «Без конта» не значить «без слідованя»: Meta бачіть ваш IP; одображіня не ґарантованé.","tags":["моніторінг жерел"]},"Threads-fara-cont":{"line":"Чітайте публічны пости з Threads без конта і зберайте їх яко текст. Неофіціалне; Meta бачіть ваш IP, а іноді треба посередніцькый сервіс.","detail":"Показує публічны пости Threads через вбудованя Meta, без конта; на выбір локалне збераня, експорт .txt. Meta бачіть ваш IP; може требовати CORS-проксі. Неофіціално.","tags":["моніторінг жерел"]},"X-fara-cont":{"line":"Достаньте ся до публічных профілів і постів на X без конта на кілько способів: прямым посиланєм, архівом, пошуком або Nitter. Зміст не чітать; посилать посиланя до archive.org.","detail":"Творить шляхы доступу без конта до публічных профілів і постів X: пряме посиланя, архів Wayback, пошук, Nitter. Не читать зміст; посылать імя користувача/посиланя до archive.org.","tags":["моніторінг жерел"]},"Arhiva-LinkedIn":{"line":"Мейте свої замітки о постах з LinkedIn, котры сте самі вставили, на єдным місці і експортуйте їх яко текст. Ґалерея хоснує офіціалне вбудованя, тому звертать ся до LinkedIn. Неофіціалне.","detail":"Архів нотаток до вручну вставленых постів LinkedIn (імпорт CSV, експорт Markdown) + ґалерея через офіціалне вбудованя LinkedIn (звертать ся до LinkedIn). Неофіціално.","tags":["архівація"]},"Cadraj":{"line":"Зберайте кліпы з TikTok руками, поґрупованы по авторах, і дывте ся на них в офіціалнім плеері. Можете позначіти, што сте уж видьли.","detail":"Ручна колекція кліпів TikTok за авторами, одтворяна через офіціалный плеєр; познака «видіто».","tags":["моніторінг жерел"]},"FASCICUL":{"line":"Переміняє телефоны в хыжі на спільну таблю на відеопроєкторі: малюнкы, замітки, образы, лазерный указатель і камера наживо. Тестованé на компютері; на справжніх телефонах іщі не перевірене.","detail":"Телефоны ↔ відеопроєктор: спільна дошка з малюваням, нотатками, образами, лазерным указателём і камерою наживо, в єднім файлі. Пряме WebRTC-споїня в локалній мережі, без стороннёго сервера; на выбір реле на телефоні з хотспотом (Android/Termux). Тестованé в Chromium; на справжніх телефонах іщі не перевірене.","tags":["співпраця"]},"INDICATIV":{"line":"Приготуйте ся на іспыт ANCOM для радіоаматорів з 723 питаньми, повторяныма в догідных інтервалах, без інтернету. Неофіціалне; база питань лем частково перевірена.","detail":"Офлайн, неофіціалный тренажер до іспыту радіоаматорів ANCOM (723 питаня, інтервалне повторяня, пошук по базі питань). Не є матеріалом ANCOM; база питань лем частково перевірена.","tags":["іспыт","радіо"]},"ETER":{"line":"Учте ся радіоаматерства в енціклопедії з Морзеовов азбуков, тренером Морзе, калькуляторами антен і пошуком по цілім змісті.","detail":"Енциклопедія радіоаматорства: Морзе, тренажер Коха, калькуляторы антен, глобалный пошук.","tags":["радіо","енціклопедія"]},"ATINGERE":{"line":"Книжка ся стає шрифтом Браля на сенсорнім екрані, з вібраціями, для глухослепых, або аудіокнижков для слепых. Не валідованé з нативныма чітачами; мать обмеджіня.","detail":"Перетворює книжкы на тактілный брайль або на аудіокнижкы. Не валідованé з нативныма чітачами; обмеженя гляньте в README.","tags":["доступность"]},"Clopotel":{"line":"Тримайте свою конференцію або воркшоп в часі: таймер для сцены з вашом програмом і сигнал, што варує, коли ся кінець приближує. По румунськы і анґліцькы.","detail":"Таймер для сцены з порядком выступів (імпорт тексту/CSV) і попереджуючім сіґналом, RO/EN.","tags":["подіі","MIT"]},"Monstrarium":{"line":"Планюйте воркшоп выробы потвор з переробленых матеріалів: додаток высчітать матеріалы і сесії і проповідать 50 потвор зо звуками, 3D і навчальнов ґров.","detail":"Плановач майстерні монстрів з рецыклованых матеріалів: сам рахує матеріалы, розклад по серіях, 50 орігіналных монстрів зі звуками, 3D і навчальна ґра.","tags":["воркшоп","MIT"]},"TranslateHub":{"line":"Выберте з 22 інштрументів на переклад або перекладайте з помочов ШІ з вашім властным ключєм. Текст, перекладаный ШІ, іде до сервісу Anthropic.","detail":"Каталоґ 22 інштрументів на переклад плюс ШІ-перекладач з вашім властным ключом. Текст для ШІ посылать ся на api.anthropic.com.","tags":["переклад","ШІ"]},"DataWeave":{"line":"Отворте таблю і розберте ся в ній: статістіка, ґрафы, зведены таблі і кореляції. Ваши дані остають на вашім пристрою.","detail":"Дослідженя CSV/TSV/JSON в єднім файлі: таблиця, статістіка, діаґрамы, зведены таблиці і кореляції; ваши дакы остають на вашім пристрою.","tags":["дані"]},"MarkdownAtelier":{"line":"Пишьте документы в Markdown і зразу видьте, як выглядають, з простыма формулами, в 7 языках, без інтернету. Тексты остають у вашім переглядачі; зробте резервну копію.","detail":"Офлайн-редактор Markdown з проглядом, GFM, підмножином LaTeX (MathML), 7 языків, пошуком і резервнов копіёв .json. Документы остають в проглядачі.","tags":["писаня"]},"RegexLab":{"line":"Выпробуйте регулярный выраз і зразу видьте, што ся з ним сходить, з поясніньми крок за кроком, тестами і варованєм, коли бы міг заморозити програм.","detail":"Тестованя реґулярных выразів JavaScript з поясніньами, тестами і застереженём про ReDoS.","tags":["розвой"]},"SEOptimum":{"line":"Перевірьте, наскільки добре є веб-сторінка приготована до пошукачів. Мать 20 інштрументів, включно з аналізов сторінкы і проглядом, як ся показує в выслідках пошуку.","detail":"20 SEO-інштрументів у проглядачі: аналіза сторінкы, попередне проглядіня SERP.","tags":["веб"]},"SEVA":{"line":"Довідайте ся більше о спаню, добовім ритмі тіла, дыханю і харчованю в енціклопедії, котру можете і слухати. Лем для інформації; не є медічна порада.","detail":"Енциклопедія доброго самопочутя: сон, циркадный ритм, дыханя, харчованя; слухованя з озвучінём. Інформатівно; не є медічнов радов.","tags":["здоровя"]},"PULS":{"line":"Што робити, док не приїде амбуланція? Порадник першой помочі по румунськы з метрономом для CPR і неповинов картков для ненаглости. Не є клінічно валідованé; волайте 112.","detail":"Порадник першой помочі по румунськы (CPR з метрономом, джгут), з пошуком і неповинов картков для ненаглости. Зміст клінічно не валідованый спеціалістом; не заміняє авторізованый курс. У ненаглім случаю волайте 112.","tags":["здоровя","ненаглость"]},"VATRA":{"line":"Што робити, коли вам бракує воды, огня або притулку в природі? Енціклопедія выжытя, без інтернету, з пошуком і замітками. Лем для навчаня; в ненаглости волайте 112.","detail":"Офлайн-енциклопедія выжываня (вода, огень, схованка, орієнтація), з пошуком і локално зберіганыма нотатками. Навчальный матеріал, не заміняє курс першой помочі; у ненаглім случаю волайте 112.","tags":["в поли"]},"Eclipsa-2027":{"line":"Видьте на мапі, де і як довго траває повне сонячне затьміня 2 авґуста 2027, з містами і пошуком місць, без інтернету. Приблизны значіня; не дывте ся на Сонце без фільтрів.","detail":"Офлайн-карта повного затьміня 2 авґуста 2027 з тривалостями, покрытём по містах і пошуком місця. Орієнтачны значіня; не дывте ся на Сонце без сертіфікованых фільтрів.","tags":["астрономія"]},"orarium":{"line":"Котра є тераз годіна на Марсі, на Місяцю або на астероїді? Видьте місцевый час наживо на 45 небесных тілах. Приблизна модель, без інтернету; не є для навіґації.","detail":"Час на каждім світі: місцевый час наживо на 45 тілах (Місяць, Марс, планеты, місяці, астероіды), темп годіны в порівнаню зо Землёв, одстань і час туды-назад, конвертор часовых поясів і мапы колонізації. Орієнтачна модель, офлайн; не на навіґацію. Містить північ і полудень на каждім тілі, вікна передачі Земля–тіло і посиланя на TerRa.","tags":["астрономія","час"]},"TerRa":{"line":"3D ґлобус і мапа, што показують день і ніч на Землі, Місяцю і планетах. Позіції сателітів можуть быти старшы приблизно на 3 місяцї, док не оновите онлайн.","detail":"3D-глобус і мапа: термінатор, Місяць, планеты. Супутникы в офлайн-режімі мають застарілый знімок (~3 місяці); для актуалных позіцій оновте онлайн. Унікалне посиланя на каждый вид; небо з любого з 45 тіл ORARIUM, звязаны в обидва боки.","tags":["астрономія"]},"Horizons.BeyondLimits":{"line":"Мандруйте історієв всесвіту од Великого вибуху до кінця, в 91 етапах. Будучность є наукова спекуляція, не певне предсказаня.","detail":"Мапа часовой осі од Великого вибуху до кінця Всесвіту: 91 подія, експорт Markdown; будучність є спекулатівна, не валідованый прогноз.","tags":["космолоґія"]},"Hyper4D":{"line":"Видьте, як выглядають чотиривымірны фіґуры: обертайте їх на екрані і дывте ся на них з кількох боків. Образы можете зберегти.","detail":"4D-ґеометрія в SVG: 3D-перерізы чотиривымірных тіл і політопів з проєкціями 4D→3D→2D, обертаныма в реалнім часі, експорт SVG.","tags":["математика"]},"ExploratoriiEco":{"line":"Польовый порадник для любителів природы: од класіфікації живых істот і їх слідів по біомы Румунії, журнал, етіка і ненаглости.","detail":"Польовый порадник для натуралістів у 20 розділах: класіфікація жывого, слідове і знакы, румунські біомы, калькуляторы, польовый журнал, етіка, ненаглы случаї і слівник.","tags":["природа"]},"FieldObserver":{"line":"Записуйте свої польовы спостереження, а телефон сам додасть дані зо своіх сенсорів. Мате архів своіх выходів.","detail":"Журнал польовых спостережінь зо сензорами телефона; архів, експорт JSON/CSV.","tags":["в поли"]},"VietAR":{"line":"Сфотьте або запишьте росліну або істоту і достаньте гадку о выді, з 519 з Румунії. Може ся мылити; ничого не їжте на тій основі.","detail":"Орієнтачна ідентіфікація 519 румунськых видів з образу/звуку; може ся мылити, не їжте росліны і ґрыбы на тій основі. Моделі ся стягують з третіх сторін; не цілком офлайн.","tags":["біодіверзіта"]},"VOIAJOR":{"line":"Слідуйте за траєкторіями Voyager 1 і 2 од 1977 по мільярд років наперед, в якімколи масштабі, од планет по Млечну дорогу. Орієнтачна модель, не навіґація.","detail":"Симуляція траєкторій Voyager 1 і 2 (од 1977 до понад мілярды років): балістічны дугы між справжніма пролетами, екстраполація з сонечнов ґравітаціёв і локалнов ґалактічнов динаміков, геліосфера, хмара Оорта і 19 близьких зірок зо властным рухом.","tags":["Voyager","сімуляція"]},"Nemurirea":{"line":"Довідайте ся, як старіє тіло і што наука гварить о біолоґічных годинах і довголітю, потім перевірте ся в квізі. Не є медічна порада.","detail":"Інтеракгівне есе про біолоґічны годіны і науку довголітя, з кінцёвым квізом. Інформатівна ціль, не є медічнов радов.","tags":["біолоґія"]},"IncredibleCosmos":{"line":"Розміщуйте планеты і звізды так, абы їх ґравітація навела комету на ціль. 108 рівнів, три складности і до трьох звізд на рівень.","detail":"Ґравітаційна ґоловоломка: розміщайте планеты і зірки так, жебы їх ґравітація навела комету на цель; 108 рівнів у 12 катеґоріях, три тяжкости, оцінка 1–3 зірок, з пошуком.","tags":["ґра","фізіка"]},"Cupa-Mondiala-2026":{"line":"Грайте на Світовім чемпіонаті 2026 і дывте ся, як ся розвивать выдуманый турнір. Выслідкы є випадковы, не предсказаня; неофіціалне.","detail":"Фікційный, неофіціалный симулятор Світового кубка 2026: випадковы результаты, не прогнозы; не звязаный з FIFA.","tags":["сімуляція","неофіціалне"]},"AGORA":{"line":"Як народило ся евро і што значіть для Румунії? 59 розділів, од Маастріхту по ЄЦБ, плюс поради для мандрівників. Неофіціалне.","detail":"Інформатівный атлас еврозоны в 59 розділах: од Маастріхту і ЕЦБ по Румунію і евро, плюс порадник для мандрівників. Неофіціалный, без правной сілы.","tags":["економіка","ЕС"]},"URME":{"line":"Приготуйте ся на пішу туру стежков Colți–Aluniș в Buzău: росліны, бурштин, скаменілости, часы сходу і заходу Сонця, выбава. Мапа не є для навіґації.","detail":"Інформатівный, неофіціалный туристічный порадник по трасі Colți–Aluniș (росліны, бурштін, скаменілости), зо сходом/заходом Сонця і списком обладнаня. Схематічна мапа, не на навіґацію; выберань у охоронній зоні заборонене.","tags":["природа","Buzău"]},"Belot-fara-frontiere":{"line":"Пізнайте белот і його сродників з інчіх країн, потім грайте при столі: ви і партнер ШІ проти двох суперників ШІ. Мать лісток для рахунку.","detail":"Атлас родины ґор belote/bela/klaverjas/jass і ґра на 4 ґравців (ви і партнер-ШІ проти двох суперників-ШІ); пріорітет має румунскый belot; запис рахунку.","tags":["карты","ШІ"]},"Scopone-fara-frontiere":{"line":"Довідайте ся, як повстав Scopone, якы мать правила і як ся одрізняють од реґіону до реґіону, потім грайте проти компютера, котрый вам може давати підказкы.","detail":"Атлас ґры scopone (15 сторінок: походжіня, правила, реґіоналны одміны) і ґра проти локалного ШІ (еврістіка / Монте-Карло), з підказками; італійскы або французскы масти.","tags":["карты","ШІ"]},"Solitaire-fara-frontiere":{"line":"Проглядайте ґры солітер, як Klondike, FreeCell або Spider, і грайте в них. Коли застрягнете, попросьте підказку або дайте компютеру розвязати.","detail":"Атлас пасьянсів (Klondike, FreeCell, Spider і інші) на спільнім двиґуні; «Підказка» од солвера з лімітом вузлів/часу і на выбір автовырішіня.","tags":["карты"]},"Sudoku-fara-frontiere":{"line":"136 выдів Sudoku, од класічного по killer або 3D, на проглядіня і ґру. Помагать поясніньми крок за кроком і розвязує ваши властны головоломкы.","detail":"Атлас 136 варіантів Sudoku (класічне, killer, jigsaw, ґреко-латинске, 3D і много іншых), з ґенератором з єдиным розвязаньом, пояснёваным розвязаньом крок за кроком, 7 режімами ґры і солвером.","tags":["головоломка"]},"Domino-fara-frontiere":{"line":"Довідайте ся історію і правила доміна, потім грайте при столі проти єдного до трьох суперників, керованых компютером. Можете одкликати хід.","detail":"Атлас доміно (походжіня, правила, наближіня) і ігровый стіл проти 1–3 ґравців-ШІ, з трёма рівнями; скасованя ходу.","tags":["доміно","ШІ"]},"Mahjong-fara-frontiere":{"line":"Пізнайте 8 варіантів mahjong і грайте солітер або ґру на чотырьох, з трєма простыма суперниками, керованыма компютером. Робить без інтернету.","detail":"Атлас 8 варіантів маджонґу, пасьянс і маджонґ на 4 ґравців (riichi, Hong Kong, Sichuan) проти 3 простых еврістічных ШІ. Офлайн.","tags":["Mahjong","ШІ"]},"Go-fara-frontiere":{"line":"Довідайте ся, одкы походить Go і як ся в него грать, потім спробуйте проти компютера, котрый вам може давати підказкы. Не посилать жадны дані по інтернеті.","detail":"Атлас ґры Ґо (18 сторінок: походжіня, правила, наближіня) і ґра проти локалного ШІ (Монте-Карло, не LLM), з SGF і підказками; без мережевых запытів.","tags":["Go","ШІ"]},"Zaruri-fara-frontiere":{"line":"26 ґр в кости на чітаня, 12 з них можете грати проти компютера, плюс сімулятор кидань з імовірностями. Без грошей; без інтернету.","detail":"Атлас 26 ґор у кости; 12 ся дають ґрати проти дідактічного ШІ (не LLM), плюс симулатор NdM з точныма імовірностями. Не є азартна ґра; офлайн.","tags":["кости"]},"Sah-fara-frontiere":{"line":"Над 700 варіантів шахів на досліджіня, з малым словарєм термінів; в многы можете грати проти компютера. Робить без інтернету.","detail":"706 записів варіантів шахів (лем дакотры з перевіреным жерелом; дакотры синтетічны) і 299 термінів лексікону. Офлайн, з локалным двиґуном до многых варіантів.","tags":["шахы"]},"Dame-fara-frontiere":{"line":"Грайте 25 варіантів шашок проти компютера і зберіть свою партію. Правила 16 з них є лем приблизны, позначены ⚠.","detail":"25 варіантів шашок, в котры ся дасть ґрати проти дідактічного ШІ, з експортом партій; у 16 правила наближены (познаčены ⚠).","tags":["шашкы"]},"Table-fara-frontiere":{"line":"Backgammon, Tavli, Narde і румунськы варіанты tabla, на чітаня і ґру: 17 варіантів проти компютера, з клавіатуров або мышков.","detail":"Ґравый атлас родины нардів: backgammon, Tavli, Tavla, Narde, Gul Bara і румунскы варіанты; 17 варіантів проти навчального ШІ; ґра з клавіатуры.","tags":["трик-трак"]},"Remi-fara-frontiere":{"line":"Пізнайте родину ґр rummy і грайте 19 варіантів проти компютера, зо статістіков. Мать 8 языків і великы, добре видны камінці або карты.","detail":"Атлас родины ґор remi (rummy): 19 варіантів проти локалного ШІ, зо статістіков; інтерфейс у 8 языках, з великыма камінцями і картами.","tags":["рамі"]},"Carti-de-joc-fara-frontiere":{"line":"Од Solitaire і Old Maid по покер: 17 карточных ґр з поясненыма правилами, 8 з них можете і зразу грати.","detail":"Інтеракгівный атлас карточных ґор, од пасьянсу і Старой дівкы по покер: 17 ґор з карточками правил, 8 з них ся дасть ґрати.","tags":["карты"]},"Undava":{"line":"Зробте квіз або грайте з приятелями, на єднім телефоні або компютері, і повторяйте питаня, на котры сте одповіли зле. Подібне до Kahoot, але незалежне.","detail":"Квіз у стилю Kahoot (незалежный), в єднім файлі: сам або по черзі на єднім пристрою, з повтором помылок. Ґра наживо є лем в серверній версії.","tags":["квіз","освіта"]},"AI-Liber":{"line":"Розправляйте з кількома асістентами ШІ з єдного місця, включно з дакотрыма, што бігають на вашім властнім компютері. Повідомлїня ідуть до провайдера, котрого выберете; ШІ ся може мылити.","detail":"Чат з многыма ШІ-провайдерами, включно з локалныма (Ollama, WebLLM). Повідомліня ідуть до провайдера, котрого выберете; одповіді ШІ можуть быти неправилны.","tags":["ШІ"]},"LocalMind":{"line":"Балакайте з малым асістентом ШІ, котрый бігать просто у вашім переглядачі. Моделі ся стягують з інтернету раз; може ся мылити.","detail":"Чат з малыма моделями (Qwen3, LFM2), запущеныма локално в проглядачі (WebGPU). Моделі походять з Hugging Face; може ся мылити. Треба локалный сервер або публічна сторінка.","tags":["локалный ШІ"]},"PromptVault":{"line":"Над 500 готовых промптів для асістентів ШІ, з котрых выберете і позначите улюблены. Не зберать ваши властны тексты.","detail":"Бібліотека 500+ промптів з облюбленыма, не є менеджером ваших властных промптів.","tags":["промпты"]},"ARENA":{"line":"Дайте двом моделям ШІ одповісти наслепо і голосуйте за ліпшу; рейтінґ ся зберать на вашім компютері. Потребуєте властны ключі.","detail":"Сліпы дуелі між ШІ-моделями з локалным рейтінґом Elo (експорт CSV). Треба ваши властны API-ключі або локалны серверы; демо-моделі є симулованы.","tags":["оцінка ШІ"]},"Nexus-fara-frontiere":{"line":"Балакайте з асістентами ШІ од кількох провайдерів, з пошуком по розмовах і збераньом. Треба інтернет і ваши властны ключі, котры ся зберають нешіфрованы.","detail":"Клієнт ШІ-чату з вашіма властныма API-ключами (Anthropic, OpenAI, Google, сумісны з OpenAI), з пошуком і експортом Markdown; «аґенты» суть промпты. Треба інтернет; ключі ся зберігають незашіфрованы.","tags":["аґенты"]},"VoiceAtelier":{"line":"Послухайте, як звучать сотні штучных голосів в десятках языків, і довідайте ся, як ся робить аудіокнижка. Онлайн проба посилать текст до зовнішніх сервісів, лем з вашом згодов.","detail":"Каталоґ 427 нейронных голосів (141 локал) і порадник до аудіокніг. Онлайн-зразок посылать текст на реле і до Microsoft, лем з вашім дозволом. Не є студіёв TTS.","tags":["голос"]},"Trusa-fara-frontiere":{"line":"Набор з 15 малых щоденных інштрументів: замітки, таблі, Markdown, паролі, фінансовый журнал і іншы. Не мать офіціалного звязку з YunoHost, котрый надхнув його категорії.","detail":"Набор 15 малых модулів, написаных з нуля (нотатки, табліця, Markdown, пароли, журнал фінансів і інше), надхненый катеґоріями додатків YunoHost; не звязаный з ним.","tags":["утіліты"]},"API-fara-frontiere":{"line":"Видьте погоду, образы NASA, позіцію МКС і десятки інчіх даных наживо на єдным місці. Треба інтернет і не было тестованé зо справжніма сервісами.","detail":"52 віджеты: 47 над публічныма API (треба інтернет; при отвераню онлайн сам звертать ся до Open-Meteo, NASA і ISS) і 5 локалных утілітів. Не тестованé на справжніх серверах.","tags":["API"]},"OmniHost":{"line":"Великый пакет над сто робочіх інштрументів, зобраных на єдным місці. Звертать ся до чотырєх зовнішніх сервісів; подробности суть в README.","detail":"Пакет продуктівности (~4 MB, 141 модуль). Звертать ся до чотирёх зовнішніх хостів; гляньте README.","tags":["набор"]},"VNTV":{"line":"Нехайте трейлеры VideoNeat ся грали як телевізійный канал, што ся не затримує. Треба інтернет; в режімі P2P ваша адреса є видна іншым дывакам.","detail":"Трейлеры VideoNeat як безперервна ТВ-програма, плюс додаток Stremio. Треба інтернет (videoneat.com, videos.trom.tf); в режімі P2P ваш IP видять іншы глядачі.","tags":["медіа","MIT"]},"OSATURA":{"line":"Оживте 2D малюнкы: наложте їх на «скелет», пустьте в рух і експортуйте анімацію в кількох форматах. Альфа-верзія, доселя мало выпробувана.","detail":"Двиґун 2D векторного ріґґінґу і анімації на Rust (кости, IK, скінінґ, фізіка, автоматы станів) зо студіёв у проглядачі і експортом до SVG, PNG, GIF, Lottie і glTF. Натівна програма (командный рядок + студія) і модуль WebAssembly, не єден файл HTML; alpha, досі мало выпробуваный. Ліценції: бібліотекы MPL-2.0, CLI AGPL-3.0-or-later.","tags":["анімація","MPL/AGPL"]},"OAZA":{"line":"Проглядайте 340 безплатных веб-сервісів, звычайно без конта, зобраных в єдным каталозі. Список быв перевіряный в юнію 2026, але не автоматічно.","detail":"Каталоґ 340 безплатных веб-сервісів третіх сторін, звычайно використовалных без конта (автоматічно не перевіряны; провірено в юні 2026).","tags":["сервісы"]},"VaultCrypt":{"line":"Мате дашто, што хочете скрыти од чужых очей? Замкніте файлы і тексты паролєм, просто в переглядачі. Страчений пароль не годно одновити.","detail":"Шіфрованя файлів і тексту AES-256-GCM у проглядачі. Незалежно не аудітованé; страчене пароль не дасть ся одновити.","tags":["безпека"]},"Akasha":{"line":"Записник з теґами, пошуком і посиланями між сторінками, котрый робить без інтернету. Абысте ничого не стратили, стягайте свіжу копію файлу.","detail":"Офлайн-нотатки в єднім файлі, з теґами, пошуком і посиланями [[Назва]]; жебы зберегти дакы, стягуйте свіжу копію файлу (quine).","tags":["замітки"]},"CLEPSIDRA":{"line":"Годіннык одчітуваня, будик і розклады на будні і на выходны дни. Рахує зо святами і вашіма властныма подіями.","detail":"Зворотный годіннік, будильник, розклады на будні/выходны, свята, події.","tags":["час"]},"Origami":{"line":"Учте ся складати папір крок за кроком: знакы, технікы і ілюстрованы моделі. Додаток запамятать, де сте скінчіли.","detail":"Порадник з оріґамі: познаčіня, техніка, моделі крок за кроком, з поступом збераным локално.","tags":["мистецтво"]},"Zicala":{"line":"Румунска приповідка на кажде день, з колекції 550. Можете шукати і зберати улюблены; коментарі были написаны з помочов ШІ.","detail":"550 румунскых приказок з приказков дня, пошуком і експортом/імпортом облюбленых; коментарі SWOT/TOWS суть створены з помочёв ШІ.","tags":["култура"]},"Limpezimea":{"line":"Чітайте sci-fi роман «Limpezimea» в семох языках. Супроводна хроніка і крітічна студія были написаны з помочов ШІ (Claude).","detail":"Науково-фантастічный роман «Limpezimea» у 7 языках, чітацке выданя. Крітічный апарат (хроніка, студія) написаный з помочёв ШІ (Claude).","tags":["література"]},"Nota-Zero":{"line":"Спекулатівна проза о теорії струн, по румунськы, анґліцькы і французькы, з замітками, што поясняють наукові ідеї. Є то фікція, не академічне жерело.","detail":"Спекулатівна фікція про теорію струн, по румунськы, анґліцькы і французьскы, з поясняючіма науковыма нотами (фікція, не академічне жерело).","tags":["література"]},"Pendulul":{"line":"Планета колышеть ся між трєма звіздами і чорнов дыров: sci-fi роман в девятєх томах, написаный Alexio вєдно з Claude. З 3D сімуляцієв, чітачом на збераня для чітаня без інтернету, EPUB і PDF.","detail":"Девятитомный науково-фантастічный роман Алексіо, написаный з Claude: планета коливать ся між трёма зірками і чорнов дыров. Містить 3D-симуляцію і чітач книжкы в єднім файлі HTML, котрый можете зберегти і чітати офлайн, плюс EPUB і PDF.","tags":["література"]},"PrintreInteligente":{"line":"Увійдьте до інтерактівного sci-fi романа з персонажами, надхненыма екіпажом Artemis 2. Рецензії суть выдуманы; переклад, голос і функції ШІ хосную зовнішні сервісы.","detail":"Інтеракгівный науково-фантастічный роман, фікція з персонажами, надхненыма екіпажом Artemis 2; рецензії суть фікційны. Переклад, онлайн-голос і ШІ-функції ужывають зовнішні сервісы.","tags":["література"]},"BorderlessMelodies":{"line":"Слухайте музику, што ся сама композує, просто в переглядачі. Можете експортувати яко аудіо, є і таймер на заспаня.","detail":"Процедурална музика у Web Audio, з експортом звуку і таймером сну.","tags":["музика"]},"EcoulSpectral":{"line":"Видьте звук яко образ, выберте часть, котра вас роздразнює, і ізолуйте або выдалте її. Мать зменшіня шуму, выявлєваня голосу і збераня до WAV.","detail":"Локалный редактор спектроґрамы: познач ділянку час–частота і ізолюй або выдалі єй; выявліня голосу, зменшіня шуму, експорт WAV.","tags":["аудіо"]},"Constelar":{"line":"Балакайте з віртуалныма компаньонами, котры памятають ваши розмовы. Звычайно одповідають по простых правилах; справжній ШІ лем коли выберете провайдера, і ваши повідомлїня ідуть до него. Лем для дорослых.","detail":"Розговорны компаньйоны з локалнов памятёв. Стандартно простый двиґун на правилах; справжній ШІ лем якщо выберете провайдера (повідомліня ся посылають до него). Для дорослых; не заміняє терапію.","tags":["ШІ"]},"Tarot":{"line":"Довідайте ся історію таро, символы карт і як ся чітають, в погляді на них яко на культурный феномен. Інтерактівный курс на ваш темп.","detail":"Інтеракгівный курс: історія, символы і читаня карт, як культурный феномен.","tags":["култура"]},"Numerologie":{"line":"Досліджуйте нумерологію яко символічну традіцію, на чотырєх рівнях з вправами, словарєм, журналом і калькулатором. Представлена без наукової валідації.","detail":"Інтеракгівный курс нумерольоґії як символічной традіції: чотыри рівні, вправы, слівник, журнал і калькулятор; поданый без наукового підтвердженя.","tags":["култура"]},"PUNCTUM":{"line":"Навчальный атлас акупресуры і терапій по точках: над 400 точок на інтерактівных мапах, рутіны самопомочі з проваджєныма сесіями, докази і безпека. Не заступать лікаря.","detail":"Навчальный атлас пунктовых терапій (акупунктура, акупресура, моксотерапія, банькы, аурікулотерапія, рефлексотерапія і інше): 410 пунктів на 14 меридіанах, 60 варіантів з рівнём доказів, SVG-мапы, ствары і рутіны, курс, квіз, флешкарткы і особисты перевіркы безпеки.","tags":["здоровя","докази"]},"Reiki":{"line":"Довідайте ся, што є Reiki, духовна практіка, і што гварить дослідженя: не было найдено досить доказів на жаден ефект окрем розслабліня. Не заступать лікаря.","detail":"Курс про Reiki, духовну практіку: огляды не находять достаточных доказів дзіаня поза релаксаціёв/плацебо; не заміняє лікаря.","tags":["култура"]},"Bioenergoterapie":{"line":"Курс, што поясняє, што є біоенерґетічна терапія і одкы походить. Практіка не мать наукового доказу лічіня і не заступать лікаря.","detail":"Курс про біоенерґетічну терапію, практіку без наукових доказів лічіня; не заміняє лікаря.","tags":["култура"]},"CHIROMANTIA":{"line":"Інтерактівный атлас хіроманціі: мапа долоні з лініями, горбами, пальцями і выдами рук, чітаный яко културна традіція, з частєв о науці і крітічнім мысліню. Без наукової валідації.","detail":"Інтеракгівный атлас хіромантії: SVG-мапа долоні (ліва/права), лінії, горбы, пальці, тіпы рук, одтиски пальців, мірїня 2D:4D, веджене читаня, флешкарткы, квіз, сліпый тест Барнума і симулатор cold reading; каждé твердженя має рівень доказів.","tags":["хіроманція","култура"]},"Radiestezie":{"line":"Перейдьте 18 рівнів о лозоходство, зо словарєм, журналом практікы і міжнародныма додаткамі. Од початку каже, же не мать наукової валідації.","detail":"Курс в 18 рівнях про лозоходство, зо слівником, журналом практікы і міжнародныма додатками; од почятку заявлять, же не має наукового підтвердженя.","tags":["култура"]},"Inforenergetica":{"line":"Довідайте ся, што твердить інфоренерґетіка, неконвенчна практіка, в структурованім курсі. Не мать наукової валідації і не є медічна порада.","detail":"Курс про інфоренерґетіку, нетрадічну практіку без наукового підтвердженя; не є медічнов радов.","tags":["култура"]},"ECLIPSA":{"line":"Довідайте ся, в котрім астролоґічнім домі припадать затьміня на вашій натальній мапі, плюс наступных 12 затьмінь. Розрахунок є приблизный, а выкладаня символічне, без наукової валідації.","detail":"До котрого астроложічного дому припадать затьміня на натальній карті, плюс наступных 12 затьмінь. Локалне, наближене астрономічне рахованя; символічна інтерпретація, астроложія не має наукового підтвердженя.","tags":["астролоґія"]},"Afrodisiace-fara-frontiere":{"line":"Чітайте о 22 стравах і росліны, традічно звязаных з жаданєм, кажда зо своім рівнєм доказів. Културный порадник для дорослых, не медічна порада.","detail":"Культурный порадник про 22 продукты і росліны, традічно звязаны з жаданём, з рівнём доказів на каждый запис. Навчальный, не є медічнов радов.","tags":["култура"]},"CalmWaves":{"line":"Амбієнтна музика, ґенерована на місці, на розслабліня і сон. Не є медічный пристрій; секція дослідженя не є незалежно перевірена. Порадьте ся лікаря (епілепсія).","detail":"Ґенератівна амбієнтна музика на релаксацію/сон. Не є медічным приладом; розділ про досліджіня незалежно не перевіреный. Порадьте ся з лікарём (епілепсія).","tags":["аудіо"]},"ASMR":{"line":"Зробте собі властный розслаблюючій звуковый краєвид з амбієнтных шарів, звуків дотыку і бінауралных ударів. Мать таймер на заспаня, а свій мікс можете ділити з іншыма.","detail":"Мікшер релаксачных звуків, ґенерованый в реалнім часі (Web Audio): амбієнтны верстві, звукы дотыку, бінауралны удары і таймер сну; мікс можете ділити.","tags":["аудіо"]},"NOMIA":{"line":"Як бы могла выглядати перша контактна зустріч людей, штучных інтеліґенцій і інчіх выдів розумів? 1001 выдуманый сценарій, фікція, не факты. Робить і без інтернету.","detail":"Концептуалный симулатор протоколів контакту Людина–ШІ–NHI, 1001 запис, компаньйон до антолоґії «Printre inteligențe». Фікція/спекуляція, не перевіреные факты; офлайн PWA, RO/EN.","tags":["фікція","спекуляція","PWA"]},"ValeaPlopului1972":{"line":"Дывте ся на случай НЛО з 1972 з вонка, зо середины і в сімуляції, реконструйованый в 3D. Є то выдумана гіпотеза, не доказ.","detail":"3D-реконструкція случая UAP у Valea Plopului (1972): зовнішній выгляд, симуляція, уявленый інтерьер. Спекулатівне, на основі неперевіреных публічных жерел, без згоды названых осіб; не є доказом.","tags":["НЛО","3D","фікція"]},"HoroScop":{"line":"Розрахуйте позіції планет на дату і місце, потім досліджуйте натальну мапу, аспекты і сумістность. Символічна астролоґія, без наукового основаня. Без інтернету.","detail":"Офлайн особиста ефемеріда: позіції планет рахованы в проглядачі (зменшена точность), натална карта, аспекты, синастрія. Символічна астроложія, без наукового підтвердженя; ліценція MIT.","tags":["астролоґія","ефемеріды","без інтернету"]},"Aurora":{"line":"Слухайте успокоюючі тоны, мягко пульсуючі звукы і слідуйте проваджєню дыханя. Лем на розслабліня, не лічіня. Робить без інтернету.","detail":"Звуковый святочище: тоны чакр, бінауралны удары і порадник дыханя, офлайн. Лем релаксація, не медіцина; частоты не мають наукового підтвердженя. Ліценція MIT; незалежный проєкт.","tags":["медітація","звук","розслабліня"]},"NumeroLogIA":{"line":"Довідайте ся, што гварять нумерологія, китайска астролоґія BaZi і біоритмы о вашій даті народжіня, з кажды розрахунок поясненый крок за кроком. Символічна сістема, без наукового основаня.","detail":"Піфаґорейска/халдейска нумерольоґія, BaZi і біоритмы в 7 языках, рахованя крок за кроком, портреты з експортом до JSON; на выбір ШІ-оракул через вашу властну модель. Символічна сістема, без наукового підтвердженя; ліценція MIT.","tags":["нумерологія","ШІ","без інтернету"]},"FrequencyLaboratory":{"line":"Выпробуйте звукы, ефекты і тесты слуху в малій аудіолабораторії. «Терапевтічны» ефекты не суть доказаны і не заступають лікаря. Без інтернету.","detail":"Звукова лабораторія в проглядачі (осцілятры, бінауралны, ефекты, аналізаторы, тесты слуху), офлайн. Лем для інформації: «терапевтічны» пресеты не мають доказаного медічного дзіаня; не є медічным приладом.","tags":["аудіо","лабораторія","без інтернету"]},"generator-frecvente":{"line":"Творте чісты тоны і пульсуючі подвійны звукы, слухайте знаны преселекції і достаньте приблизну перевірку свого слуху. Не є медічный пристрій. Без інтернету.","detail":"Ґенератор тонів у проглядачі (бінауралны, секвенцер, EQ, орієнтачный тест слуху, пошук пресетів), офлайн. Лем для інформації: пресеты Solfeggio/Schumann не мають наукового підтвердженя; не є медічным приладом.","tags":["аудіо","ґенератор","без інтернету"]},"ACORDAJ":{"line":"Проглядайте над тысячу духовных курсів і ініціацій, з історічным контекстом і крітічным поглядом. Не звязаный з сайтом-жерелом і без наукової валідації. Без інтернету.","detail":"Офлайн-атлас 1134 духовных курсів/ініціацій (список з cursurispirituale.webnode.ro, незалежно), з історічным контекстом і крітічным розсудом; без наукового підтвердженя.","tags":["духовность","атлас","крітічне розсудженя"]},"Profund":{"line":"150 питань, котры выводять розмову за рамкы пустой бесіды, між приятелями або в родині. Грайте їх на екрані або выдрукуйте, з неповинным таймером.","detail":"Ґра зо 150 питань на змістовны розговоры (RO/EN/FR), онлайн або друкована, з ґравцями і таймером на выбір; адаптована з deepcards.org, орігіналы остають властностёв властителів прав (MIT лем на код і орігіналну часть).","tags":["розмова","карты","trade-free"]},"Universul-Observabil":{"line":"Яке велике є Всесвіт, котрый можеме видьти? Порівнайте три мапы (лінійна, плоска, в просторі) і робте космолоґічны розрахункы. Чісла не суть незалежно перевірены.","detail":"Сторінка-хаб, котра представлять і порівнює 1D, 2D і 3D візуалізації спостережного Всесвіту, з офлайн-космолоґічным калькулятором; дакы і рекорды з катальоґу май 2026, незалежно не перевіреные. RO/EN.","tags":["астрономія","космолоґія","візуалізація"]},"Universul-Observabil-1D":{"line":"Выйдьте од нас і мандруйте до краю видного Всесвіту, минаючи 112 ґалаксій, розміщеных на єдній осі. Іронічный тон, округлены значіня, навчальна ціль.","detail":"1D-мапа спостережного Всесвіту: 112 ґалактік на радіалній осі (час, одстань, червене зміщіня), з табліцёв дат і експортом CSV. Навчальна, з іронічным тоном; округленé значіня, рекорды на дату катальоґу (май 2026).","tags":["астрономія","космолоґія","візуалізація"]},"Universul-Observabil-2D":{"line":"Мапа ґалаксій в сатіричнім выданю «Плоска Земля»: жарт, Земля не є плоска. Зумуйте міджі 111 ґалаксіями; одстані суть приблизны. Без інтернету.","detail":"Інтеракгівна 2D-мапа спостережного всесвіту (111 ґалактік, лоґарітмічна шкала, дакы JWST) в сатірічній выданю «Плоска Земля»: пародія, Земля не є плоска; одстані наближены. RO/EN, офлайн.","tags":["астрономія","сатіра","космолоґія"]},"Universul-Observabil-3D":{"line":"Летьте міджі над 115 ґалаксіями на 3D мапі, з проваджєныма турами і выкликами. Значіня суть приблизны.","detail":"Інтеракгівна 3D-мапа (WebGL) спостережного всесвіту: 115+ ґалактік, 12 горізонтів, 30 турів, вызвы в порадникові, експорт GLB/CSV/BibTeX. Наближены значіня; рекорды JWST на май 2026.","tags":["астрономія","космолоґія","3D"]},"QSO":{"line":"Ведьте облік радіозвязків зо своєй радіоаматорськой станціі, з часом UTC, локаторами і статістіков. Неофіціалне; розрахункы суть приблизны.","detail":"Неофіціалный журнал радіоаматорской станції: QSO з годінніком UTC, імпорт/експорт ADIF 3.1, локаторы Maidenhead, перевірка дублікатів, статістіка. Часткова табліця префіксів (не DXCC); наближены рахованя.","tags":["радіо","журнал"]},"Curatitor":{"line":"Видьте, што ваши фото і файлы выдають (місце, камера, автор), і выдалте тоты дані перед посланєм. Не скрывать лица або інчій видный зміст.","detail":"Показує і выдаляє метадакы файлів локално (GPS, камера, автор, софтвер) без перекодованя пікселів або звуку і наново перевіряє результат. Не анонімізує зміст (лиця, шум сензора).","tags":["метадані","приватность"]},"Poteca":{"line":"Отворте траскы, записаны під час туры або їзды на байку, і видьте одстань, підыйдіня і профіль высоты. Можете их і стригати або спойовати. Без мапы; підыйдіня є оцінене.","detail":"Переглядач і редактор треків GPX/GeoJSON/KML/CSV: статістіка, профіл высоты, вырізованя, злучіня, спрощіня, експорт. Без основной мапы; підйом/спуск суть оцінкы.","tags":["GPX","траски"]},"Orar":{"line":"Календар і тыждньовый планер на день, тыждень або місяць, з румунськыма державныма святами. Будикы дзвонять лем, покы сторінка остає отворена.","detail":"Календар і тыжньовый плановач: вигляды місяць/тыждень/день/порядок дня, повторіня RFC 5545, часовы пояса, румунські державны свята, імпорт/експорт .ics. Будильникы дзвонять лем покы є отворена вкладка.","tags":["календар","час"]},"Alfabete":{"line":"Учте ся і практікуйте Морзе, шрифт Браля, фонетічну азбуку, флаґовый семафор і стары шіфры, потім выдрукуйте лісток. Стары шіфры не охороняють тайны.","detail":"Довідник, конвертор, тренажер і друковный листок до Морзе, брайля (ступінь 1), фонетічных алфавітів, семафора, Бодо, числовых сістем і класічных шіфрів. Класічны шіфры не дають безпекы.","tags":["кодуваня","навчаня"]},"Fabrica":{"line":"Напишьте курс яко простый текст і переміньте его на сторінку з лекціями, фіналным тестом і печатным сертіфікатом. Сертіфікат не мать офіціалну вагу.","detail":"Фабрика курсів і квізів: напишіть курс звычайным Markdown і експортуйте єго як єден самодостатній файл HTML з локалным поступом, кінцёвым тестом і друковным сертіфікатом (без акредітацийной вартости).","tags":["курсы","авторство"]},"Bolta":{"line":"Як выглядало небо над вами, в якімколи місці і в якыйколи день між 1900 і 2100? Видьте Сонце, Місяць, планеты і звізды, плюс затьміня 2027. Значіня суть розрахованы, не офіціалны. Без інтернету.","detail":"Офлайн-планетарій на любе місце і час між 1900 і 2100: Сонце, Місяць, планеты, 1627 зірок, сузірья, події і сторінка про затьміня 2027. Рахованé значіня, не офіціалны.","tags":["астрономія","планетарій"]},"BRAZDA":{"line":"Розкодуйте Golden Record з Voyager крок за кроком, потім закодуйте новый диск для сонды, выпущеной тераз. Образы в перших крокох суть схематічны, не от NASA.","detail":"12-крокный декодер і кодер Voyager Golden Record: швыдкість, водневый годіннік, мапа пульсарів, сіґнал образа, каліброваня з колом, декодованя рядок за рядком, колір, ваш властный файл, внескы і кодованя диска 2026–2027.","tags":["Voyager","сіґнал"]},"Arbore":{"line":"Збудуйте своє родовидне дерево, з людьми, родинами, часовов лінійов і калькулатором споріднєности по румунськы. Дані остають лем в тім переглядачі, без сінхронізації.","detail":"Локална ґенеалоґія: особы, родины, імпорт/експорт GEDCOM 5.5.1, SVG-діаґрамы, часова лінія, калькулятор споріднености (лем румунска термінолоґія). Без синхронізації; дакы остають в тім проглядачі.","tags":["ґенеалоґія","GEDCOM"]},"Gospodar":{"line":"Ведьте облік грошей в господарстві: рахункы, выдаткы, місячны бюджеты і звіты. Конто не треба, але коли стратите пароль, стратите дані. Не є фінансова порада.","detail":"Локалный домашній бюджет: конта, катеґорії, транзакції, імпорт CSV, місячны бюджеты, звіты і калькуляторы з проэрачныма формуламы. Без конта і синхронізації; страчене пароль значіть страчены дакы. Не є фінансовов радов.","tags":["бюджет","особисты фінансы"]},"Decibel":{"line":"Змірьте, як голосный є окружный шум, і видьте, з яких звуків ся складать. Мать і орієнтачный тест слуху. Не є сертіфікованый пристрій; выслідкы залежать од мікрофона.","detail":"Мірач гучности, спектральный аналізатор (1/3 октавы, FFT) і орієнтачный тест слуху. Не є сертіфікованым мірачом і не має правной або медічной вартости; показникы залежать од мікрофона і калібраціі.","tags":["звук","змірюваня"]},"Provenienta":{"line":"Мате образ і хочете знати, хто его підписав і якы правкы заявляє? Перевірьте приложеный цыфровый підпис. Експерімінталне, тестованé лем на зразкових файлах.","detail":"Локалный, експеріменталный перевіряч C2PA / Content Credentials: показує, хто підписав і котры правкы были заявлены, і перевіряє підпис і звязок з байтами файлу. Тестованый лем на синтетічных файлах; без списку довіря.","tags":["C2PA","походжіня"]},"Lexicon":{"line":"Принесте свої словарі і шукайте в них слова, хоць бы сте писали без діакрітік або з помылками. Приходить лем з малым демонстраційным набором. Без інтернету.","detail":"Офлайн-двиґун словників: прінесте свої словникы (TSV/CSV, JSON, StarDict, dictd, XDXF) і шукайте по початку слова, без огляду на акценты, приблизно або по цілім тексті. Включеный набор (345 записів) є демо, не повный словник.","tags":["словарь","язык"]},"VERIGA":{"line":"Находить зломлены посиланя на веб-сайті або в папці, плюс файлы без призначіня. Бігать на Windows, macOS і Linux; вымагать дакуй компютерной обізнаности.","detail":"Перевіряч посилань (clean-room) для вебсайтів і локалных папок, написаный на Rust: командный рядок, натівна десктопна програма (egui) і версія HTML в єднім файлі. Перевіряє посиланя HTML і CSS, переадресації, якоры #fragment, осиротілы файлы, robots.txt і sitemap. Windows, macOS і Linux; ліценція MIT.","tags":["перевірка посиланєв","MIT"]},"TEZAUR":{"line":"Асістент для вашой дисертації, котрый пише лем з ваших властных кніг і статей, з перевірныма цітатами. Бігать на вашім компютері; ваши документы го ніколи не опущають. Робота ся іщі проваджать.","detail":"Локалный дослідницькый помічник на писаня дипломной роботы, написаный на Rust, з одповідями, звязаныма з цітатами: індексує ваши книжкы і статі (PDF, EPUB, DOCX, txt), знаходить уривкы і пише лем з них, з перевіреныма цітатами [n] і списком літературы. Працює на вашім компютері з локалнов моделёв (Ollama, Jan, LM Studio); ваши документы єго ниґда не покидають. Версія 0.x; ліценція MIT.","tags":["дослідженя","MIT"]},"LegatorOCR":{"line":"Скануйте книжку і достаньте чістый PDF з выровнаныма сторінками і текстом, в котрім можете шукати. Бігать на Windows, macOS і Linux; ваши скані остають у вас.","detail":"Clean-room постобробник на Rust для сканованых книжок: ділить подвійны розвороты, выправлять нахыл, обтинать, наставлять поля, чістить і бінарізує, потім експортує PDF або образы з OCR-текстовым верствов з пошуком. Ґрафічна програма (Windows, macOS, Linux) і командный рядок, в 8 языках. Розпознаваня тексту (OCR) потребує окремой програмы Tesseract; уся остача працює без неё. Версія 0.x; ліценція MIT.","tags":["сканованя","MIT"]},"Fenarium":{"line":"Атлас і воркшоп суб'єктівных сприйматєв через вшытки змыслы, почінаючі з фосфенізму: 13-модулный курс, проваджєны експерімінты, візуалный сімулятор і лабораторія рандомізованого A/B самоексперіменту. Навчальне, не медічный пристрій.","detail":"Атлас фенів (фосфены, послідовны образы, звукы як при тіннітусі і інше), курс з 13 модулів, лабораторія самоекспериментів; не є медічным приладом.","tags":["сприйматя","MIT"]},"MENSURA":{"line":"Змірьте свій IQ, EQ, CQ, RQ, выконавчы функції і змыслы 18 тестами в 6 областях, з складеныма індексами і 95% довірчіма інтервалами. Тимчасовы норми, лем орієнтачны, не діаґноза.","detail":"18 тестів у 6 областях (IQ, EQ, CQ, RQ, виконавчы функції, чутя), індексы з довірчіма інтервалами, експорт/імпорт JSON; провізорны норми.","tags":["тесты","MIT"]},"Cronosala":{"line":"Таймеры для фітнесу: одпочінок між серіями, HIIT, Tabata, EMOM, AMRAP, околы і метроном, плюс тренувальный журнал з кг і повторєніями.","detail":"Таймеры до спортзалу і журнал тренінґів в єднім файлі HTML: адаптівна пауза між серіями, Interval/HIIT, Tabata, EMOM, AMRAP, станційны кола, темп, метроном, 4-тыжньова місячна програма, каталоґ вправ і QR-кодв до тренажерів. Дакы остають в проглядачі; інтерфейс по румунськы.","tags":["спорт","час"]},"ScutSonor":{"line":"Голосный звук і блискаючій ліхтарик проти агресівных псів, плюс порадник поведіня. Помічник, не ґарантованый щит.","detail":"Ґенерує розгортку 2–8 kHz, експеріменталный ультразвук, сірену і тест дінамика, з лімітером, котрый тримать гучность, стробоскопом ліхтарика (2,5 Hz), деннім режімом і порадником безпеки. Єден файл, без слідованя. Докази, же звук одстрашує псів, суть слабы.","tags":["безпека","звук"]},"MIRAJ":{"line":"Як сітківка видить і як мозок будує образ: ямка, сліпа пляма, ілюзії і квіз, на трєх рівнях.","detail":"Інтеракгівне пояснїня зору на трёх рівнях (початковый, середній, поглублёный): сітківка, ямка, сліпа пляма, оптічны ілюзії, резюме і квіз з 10 питань. Єден файл, інтерфейс по румунськы і анґліцькы.","tags":["зір","освіта"]},"ANTROPOS":{"line":"Орієнтачный науковый профіль, розрахованый локално: біолоґічный вік PhenoAge, голос, почерк, малюнок годінника, особистость TIPI і час реакції.","detail":"Навчальный скрінінґовый інштрумент, не діаґноза: біолоґічный вік PhenoAge з ґардом правдоподобности, аналіза голосу, ґрафометрія почерку, тесты годінніка і малюнка людини, TIPI, тесты реакції, друковный звіт і експорт JSON. Дакы остають в проглядачі.","tags":["скрінінґ","біолоґія"]},"DESCANTAR":{"line":"Ворожіня на бобах з 41 бобом (метода 3×3, олтеньскый варіант) і 12 традічных замовлянь, яко предмет фолклорного дослідженя.","detail":"Румунске ворожіня на бобі трёма методами (3×3 по книжці, Oltenia, три купкы), читаня по Голові, Серцю і Ногах, 12 традічных заклинань, фаза місяця, лічіль рецітації, ґенератор заклинань, історія і порадник до копіюваня. Фолклорный зміст переложеный на 8 языків з помочёв ШІ, нереценізованый нативныма мовцями.","tags":["фолклор","бобы"]},"Index-fara-frontiere":{"line":"Каталоґ додатків з єдным HTML-файлом: колекція chiuta.github.io плюс зовнішні ресурсы, з пошуком і теґами.","detail":"Осем проєктів з колекції автора і осем зовнішніх ресурсів, чітко позначеных, з пошуком наживо, клікабелныма теґами, перемикачом RO/EN, темнов/світлов темов і записом, котрый каталоґізує сам себе. Без мережевых запытів. Статічный знімок з 5 юла 2026.","tags":["каталоґ","ресурсы"]},"DECUPAJ":{"line":"Переміньте подкаст, аудіо або відео, на вертікалны кліпы з субтітрами, просто в переглядачі, без конта і без водяного знаку. Ваши файлы ніколи не опущають пристрій.","detail":"Вертікалны reels з подкасту (звук або відео) в єднім файлі HTML: выберте сеґмент на ґрафі звукової хвылі, достаньте пропозіції моментів, локалне переписованя з Whisper, стілізованы субтітры, 4 формата кадру (9:16, 4:5, 1:1, 16:9), чергу експорту і MP4 через WebCodecs. Інтерфейс у 8 языках.","tags":["рілс","відео"]},"LECTOR":{"line":"Книжкы начитаны просто в переглядачі: EPUB, DOCX, PDF, TXT або вставленый текст, без конта і без сервера. Текст ніколи не опущать ваш пристрій.","detail":"Слухайте книжкы, читаны вголос, з єдного файлу HTML: EPUB, DOCX, PDF (з румунскым OCR на скены), TXT; ґолосы пристрою або Piper ro_RO, выділіня выповідженого слова, таймер сну, розділы, закладкы, словник вымовы, локална бібліотека і теміы для дислексіков. Інтерфейс у 8 языках.","tags":["аудіо","книжкы"]},"FARFURIA":{"line":"Безплатный цыфровый дієтолоґ: персоналізованы калоріі і макро, 7-деньный плян стравы, харчовый дневнік і слідованя ваги. Не заступать лікаря або дієтолоґа.","detail":"Цифровый дієтолоґ в єднім файлі HTML: цілі калорій і макроживін (Mifflin–St Jeor, рівень активности, цель), 7-деннный план страв з фільтрами дієт і алерґенів, база продуктів, харчовый щоденник і слідованя ваґы. Правила безпеки для неповнолітных, історії розладів харчованя і хворобы нырок. Інтерфейс у 8 языках.","tags":["харчованя","здоровя"]},"VITALIS":{"line":"Приватный компаньон для здоровя, довголітя і біохакінґу: девять стовпів, упорядкованых по доказах, калькулаторы, оцінка способу жытя і щоденный ритуал. Не є медічна порада.","detail":"Компаньйон здравя і довголітя в єднім файлі HTML: девять стовпів, упорядкованых по доказах, калькуляторы (HOMA-IR, TyG, талія-до-росту, Mifflin–St Jeor, зоны пульсу, цыклы сну, білок), таймер постіня, тренажер дыханя, оцінка 360 з радарнов діаґрамов, референтны діапазоны біомаркерів і слідованя деннного рітуалу. Неофіціалный компаньйон події BioHacking360. Інтерфейс у 8 языках.","tags":["здоровя","довголітя"]},"REZONANTA":{"line":"Порадник і інштрументы для комунікації і медіа: повідомлїня, каналы, пресове повідомлїня, інтервю, ясность, плян і кріза.","detail":"Як зробити, жебы вас слухали, в єднім файлі HTML: 12 принціпів з практічным тестом, «дом повідомліня» (30-секундна презентація, пост, коротка і говорена версія), рекомендації по медіальных каналах, ґенератор пресрелізу в обернёній пірамідї, листок інтервю, аналізатор ясности тексту, плян комунікації з експортом текст/CSV і кроки першой годины кризы. Інтерфейс у 8 языках.","tags":["комунікація","медіа"]},"Claritas":{"line":"Росшырїня для переглядача «все в єднім» для доступности: справа контрасту, режім чітаня, чітаня вголос і аудіт WCAG. Без телеметрії, без мережі, без конта.","detail":"Безплатне розшіріня доступности для проглядача: автоматічна справа контрасту (WCAG AA/AAA), контрастны теми, фільтры проти дальтонізму, більшый текст і шріфты для дислексіков, лінійка, маска і лупа для читаня, режім чітача, озвучіня, великы цілі кліку і сканованя єдным перемикачом, аудіт WCAG 2.2, локалны знімкы екрана і запис екрана. Для Chromium, Firefox і Safari; інтерфейс у 8 языках.","tags":["доступность","росшырїня"]},"TurboCursa":{"line":"Псевдо-3D аркадны перегоны, написаны в Rust: краєвиды ґенеровані з зернятка, 11 режімів, кар'єра по дівізіях і 2 ґравці. Оріґіналне, без коду або ресурсів з іншой ґры.","detail":"Clean-room псевдо-3D аркадны ґоночны на Rust: орігінална двиґун, ґрафіка, музика і назва, усе ґенероване зо зерна (19 краєвідів), кампанія, часовый заїзд, безкінечный, Rush Hour, слалом, дзеркалный, Blackout, Zen, проти CPU, екран на двох і кар'єра в дівізіонах. Працює натівно або як вебфайл; інтерфейс у 8 языках.","tags":["перегоны","Rust"]},"ANTENA":{"line":"Робота ся проваджать: розвязувач дротовых антен сумістный з NEC-2 (метода моментів) з веб-інтерфейсом. Доселя лем пре-альфа скелет.","detail":"Робота в проґресі: NEC-2-сумісный солвер дротяных антен (метод моментів) з веб-інтерфейсом у проглядачі. Поки лем скелет pre-alpha.","tags":["радіо","антены"]},"ARBITRU":{"line":"Робота ся проваджать: універсалный двигун правил для настольных, карточных, костяных і головоломных ґр, з декларатівнов мовов правил. Доселя лем пре-альфа скелет.","detail":"Робота в проґресі: універсалный двиґун правил до настолных, карточных, костяных ґор і ґоловоломок, з декларатівнов мовов правил. Поки лем скелет pre-alpha.","tags":["ґры","правила"]},"ASTROLABIU":{"line":"Робота ся проваджать: двигун небесных подій (шкалы часу, затьмінья, схід і захід, календарі), чістый Rust. Доселя лем пре-альфа скелет.","detail":"Робота в проґресі: двиґун небесных подій (шкалы часу, затьміня, схід і захід, календарі), на чістім Rust. Поки лем скелет pre-alpha.","tags":["астрономія","календарі"]},"ECOGRAMA":{"line":"Робота ся проваджать: редактор спектроґрамы і реставрація аудіа: выберте на спектроґрамі, справте, експортуйте. Доселя лем пре-альфа скелет.","detail":"Робота в проґресі: редактор спектроґрамы і реставрація звуку: выберте на спектроґрамі, справте, експортуйте. Поки лем скелет pre-alpha.","tags":["аудіо","реставрація"]},"ecou-spectral-rs":{"line":"Робота ся проваджать: нативный редактор спектроґрамы в Rust з плаґінами на зменшіня шуму і выявлєваня голосу. Мать скелет коду і формат плаґінів, але іщі ани єдна готова функція.","detail":"Робота в проґресі: натівный редактор спектроґрамы на Rust з плаґінами на зменшіня шуму і выявліня голосу. Має скелет коду і формат плаґінів, але іщі ніяку готову функцію.","tags":["аудіо","Rust"]},"MARTOR":{"line":"Робота ся проваджать: судова веб-фіксація в WARC/WACZ з гешами, підписами і довіреныма часовыма значками, перевірна без інтернету. Доселя лем пре-альфа скелет.","detail":"Робота в проґресі: судово-експертне захопліня веб-сторінок у WARC/WACZ з хешами, підписами і довіреныма часовыма печатками, перевірюване офлайн. Поки лем скелет pre-alpha.","tags":["архівація","докази"]},"NEAMURI":{"line":"Робота ся проваджать: двигун споріднєности, од шляху в родовидным дереві до правильного терміну родины в многых языках. Доселя лем пре-альфа скелет.","detail":"Робота в проґресі: двиґун споріднености, од шляху в родиннім древі до правильного терміна родича в многых языках. Поки лем скелет pre-alpha.","tags":["споріднєность","ґенеалоґія"]},"TACTIL":{"line":"Робота ся проваджать: шар дотыковых выходів: формат Браля (BRF, Unicode), дісплеї, ембосеры і вібрація сенсорного екрана. Доселя лем пре-альфа скелет.","detail":"Робота в проґресі: верства тактілного выводу: формати брайля (BRF, Unicode), дісплеї, друкарькы з рельєфом і вібрація сенсорного екрана. Поки лем скелет pre-alpha.","tags":["шрифт Браля","доступность"]},"atelier-verificare":{"line":"Перевірьте фото, відео, посиланя і домены у вашім переглядачі, ничого ся не загружать: справжній тип файлу і SHA-256, EXIF/GPS, XMP/IPTC, Content Credentials (лем чітаня), аналіз рівня помылкы. Не може доказати, же фото є справжнє. Альфа.","detail":"Набор інштрументів перевіркы для журналістів і уважных чітачів, котрый працює локално. Додайте образы, відео, посиланя, домены або текст і достаньте выснівкы з рівнём побоїня до каждого: справжній тіп файлу, SHA-256, EXIF і позіція GPS, XMP і IPTC, слідове ШІ-ґенераторів образів, маніфесты Content Credentials (C2PA; чітаны, не валідованé), аналіза рівня помылок для JPEG, метадакы відео з ключовыма кадрами до зворотного пошуку образів і анатомія посилань. Дві необовязковы мережевы перевіркы (резюме DNS, Internet Archive) пускають ся лем по позначеню позвілу. Звіт (Markdown, JSON або PDF) выписує границі методы. Не може доказати, же фото є автентічне: брак метадат мало значіть, а метадакы дасть ся підроблити. Alpha; девять з єдинадцятёх перевірок працює офлайн; файлы остають в проглядачі.","tags":["журналістіка","верификація","фото"]},"balanta":{"line":"Порівнюйте моделі ШІ наслепо: вставте одповіді двох до осмох моделей на 92 промпты по румунськы, анґліцькы і мадярськы, голосуйте A або B і достаньте рейтінґ з інтервалами. Альфа; робить без інтернету.","detail":"Сліпе порівнёваня ШІ-моделей по румунськы, обабоку. Одповіді каждой моделі вставляте сами (ничого ся не волать: без API-ключів, без конт), додаток ховать назвы моделей в одповідях, ставлять порядок зо зерна і записує ваш голос. Рейтінґ ужывать Bradley–Terry і Elo з 95% інтервалами bootstrap, плюс частоту перемог, упередженость позіції і табліці прямых порівнань. Голосы і одповіді суть отвореныма файламы JSON Lines. При малім чіслі голосів або промптів рейтінґ ничого загалного не говорить. Alpha; дакы остають в проглядачі; без слідованя.","tags":["ШІ","оцінка"]},"calendarium":{"line":"Напишьте дату в єднім з одинадцятєх календарів (ґреґоріаньскый, юліаньскый, жидівскый, хіджра, перськый, китайскый, майя, Марс…) і видьте її в вшыткых іншых, з місячным поглядом. Альфа; робить без інтернету.","detail":"Перетворює дакы між єдинадцятёма календарями (ґреґоріанскый, юліанскый, Revised Julian, єврейскый, Hijri, перскый, коптскый, етіопскый, чінскый, майя і Mars Sol Date), показує Julian Day, день тыждня і тыждень ISO, і має місячный вид з другым календарём під каждым днём. Містить румунскы нотатки (старый і новый стіль, перехід 1919, Великдень) і атлас календарів, єден плаґін на календар. Значіня суть рахованы, з заявленыма границями (Hijri є табулярный; діапазоны суть захищены). Alpha, у 8 языках, працює офлайн; без слідованя.","tags":["календарі","час"]},"glosar":{"line":"Словарь без інтернету для аромуньской, меґленорумунськой і ромськой мов: шукайте без діакрітік, видьте, котрых основных слов бракує, додавайте слова з жерелом і записом. Альфа.","detail":"Словникы языків меншін і загрожіных языків, створены іх мовцями. Шукать без огляду на діакрітікы, показує певность (чорновік, з жерелом, перевіреный), має табліцю покрытя 50 основных понять і дозволят додавати слова з жерелом, ліценціёв і записом (до 50 KB). Експортує файлы TSV і Anki і файл внеску для проєкту. Стартовы списки суть малы — чісловникы і дакілько слів, каждé з опублікованым жерелом — і ніякый мовец іх іщі не перевірив. Alpha; працює офлайн; дакы остають в проглядачі, док іх не стягнете.","tags":["языкы","словарі"]},"graiul":{"line":"Архів румунського фолклору (приповідкы, замовляня, загадкы, колядкы) без інтернету, з жерелом, повітом і згодов. Почінать з десятєх приповідок; можете додавати далшы. Альфа.","detail":"Пошук без огляду на діакрітікы, з фільтрами по тіпу, жупы і певности; приказка дня (єдна для вшыткых в даный день), схематічна плиткова мапа 41 жупы і Бухарешту, і форма додаваня, котра вымагать жерело і, для заклинань і всёго зібраного од особы, згоду. Експортує файл внеску і TSV. Стартовы дакы суть десять румунскых приказок з Wikiquote; ніяку не перевірив фолклорист. Alpha; працює офлайн; дакы остають в проглядачі, док іх не стягнете.","tags":["фолклор","архів"]},"indicativ-international":{"line":"Практікуйте питаня з іспытів радіоаматорів з пятьобоксовым розкладом повторєваня і тестовыма іспытами на час; імпортуйте пакеты питань в єдным спільным форматі JSON. Включеных 50 практічных питань; не є офіціална база. Альфа.","detail":"Тренажер і симулатор іспыту на питаня до ліценції радіоаматора, зо спільным форматом пакетів, жебы каждá країна могла додати свою базу. «Тренінґ» повторює правилны одповіді по 1, 3, 7, 14 і 30 днях і пояснює кажду одповідь з єй жерелом; «Іспыт» є тест на час з прогом; «Пакеты» імпортує і перевіряє пакеты і резервує ваш поступ. Вбудованый пакет має 50 орігіналных тренувалных питань, написаных на цей проєкт — не є офіціална база — і пакет ніякой країны іщі не є включеный. Alpha; працює офлайн; поступ остає в проглядачі.","tags":["радіо","іспыты"]},"proiector-fara-frontiere":{"line":"Телефоны в класі ся стають спільным екраном, без сервера і без конта: таймер, опытованя, квіз, замітки і табля, спарованы QR-кодом або вставленым текстом в тій самій мережі. Альфа: іщі не выпробуваны на справжніх телефонах.","detail":"Спільный екран до класы, без сервера і без конта. Учитель отворять сторінку на проєкторі; телефон каждого ученика приєднує ся обміном кода (кадры QR, фото кода або вставленый текст), до 30 телефонів наразь. Включено пять активностей: таймер зворотного одліку, голосованя з барами наживо, квіз (питаня з файлу JSON, звычайного тексту або CSV; правилна одповідь остає на проєкторі, док єй не одкрыють; бонус за швыдкость і табліця результатів), липкы картікы і дошка з єдным цвітом на телефон. Результаты можете зберегти як CSV, текст або PNG. Каждá активность працює в ізолованім фреймі лем з дозволами, котры заявила, а нова активность є єден дескріптор і єден скріпт. Учитель може заблоковати або выдалити телефон і закінчити сесію; каждый пристрій сам выберать мову (осем) і выгляд (темный, высокый контраст, великый текст). Після отвераня працює офлайн і дасть ся інсталовати. Alpha: тестованé в Chromium зо справжніма споїнями на єднім компютері, не на справжніх телефонах, не в іншых проглядачах і не в шкільных мережах. Спарёваня потребує тоту саму локалну мережу (без реле), показує IP-адресу каждого пристрою другому і не перевіряє, хто є другый пристрій. Формат квізу «Undava» не є підтримуваный: специфікацію не найдено.","tags":["класа","проєкція","квіз"]},"regula":{"line":"Грайте пять класічных ґр для двох (Nine Men’s Morris, Alquerque, Fanorona, Mū tōrere, Hnefatafl) проти компютера або приятеля; додайте властну ґру яко JSON. Альфа; робить без інтернету.","detail":"Єден двиґун правил до традічных настолных ґор: каждá ґра є файл JSON, а текст правил у осьмох языках ся ґенерує з тых самых дат, по котрых ґрать двиґун, тому текст і ґра ся не можуть розходити. Каждá сторона може быти людина, випадковый ґравець або компютер на двох рівнях; скасованя, повтор, підказка і запис ходів, котрый можете скопіровати. Можете вставити, перевірити і ґрати свою властну ґру. Ґры суть реконструкції, не турнірны правила, і каждá заявлять, на скілько є певна в своіх правилах. Alpha; працює офлайн; без слідованя.","tags":["ґры","правила"]},"vietar-packs":{"line":"Проглядайте, імпортуйте, перевіряйте і творте реґіоналны пакеты выдів для VietAR: назвы в многых языках, прізнакы ядовітости, подібны выды. Пять чорновых стартовых пакетів з 71 выдом. Альфа; робить без інтернету.","detail":"Реґіоналны пакеты видів до VietAR: назвы в многых языках, познака токсічности, небезпечны подобны выды і місце на ліценцованы фото і посиланя на звукы. Проглядайте і шукайте в пятёх стартовых пакетах (Румунія: росліны і ґрыбы, птахы, звірята; Болгарія і Молдова: скелеты), імпортуйте пакет, перевіряйте єго тыма самыма правилами як репозіторій або створте єден для шкільной класы або клубу природы. Стартовы пакеты суть чорновікы без фото і звуків, а «не позначенé як токсічне» ниґда не значіть їстне або безпечне. Додаток VietAR іщі не годен імпортовати пакеты. Alpha; працює офлайн.","tags":["природа","выды"]},"PatruZeci":{"line":"Ілюстрованый, анімованый атлас хоснованя WD-40: порадник з 147 карт і офіціалный список 1993 хоснованєв, кажде зо своєв анімованов сценов. Неофіціалне, без інтернету, без конта.","detail":"Ілюстрованый, анімованый атлас ужываня спрею WD-40 в єднім офлайн-файлі: порадник зо 147 карток у 14 катеґоріях (з рівнём ризіка і тым, што спрей робить), офіціалный список «2000+ ужываний» з 1993 записами і розділ з 25 додатковыма ужываньами, міфами і застереженями зо статей з веба. 131 анімованый варіант сцен, фільтры по катеґорії і функції, інтерфейс у 8 языках. Неофіціалный, незалежный додаток.","tags":["WD-40","DIY"]},"ODISEEA":{"line":"Документалный фільм на приблизно 4,5 хвілины о Voyager 1 і 2, в єдным файлі HTML: сцены, ґенеровані на ґрафічній карті, експорт 2D і 3D для VR окуляров, в 8 языках.","detail":"Документ на около 4,5 хвылін про зонды Voyager 1 і 2, в єднім файлі HTML, котрый працює локално в проглядачі, без сервера і без інсталації. Процедурны сцены, ґенерованы на ґрафічній картї (WebGL): планеты, зонд, ракета, антена DSN, Golden Record, геліосфера, Pale Blue Dot. Публічны образы NASA/JPL і Wikimedia Commons або ваш властный образ до каждой сцены. Експорт у 2D, половіном (1920×1080) і повнім (3840×1080) 3D side-by-side, і режім телефона до VR-окулярів як VR BOX; амбієнтна музика, ґенерована в проглядачі, на выбір коментар. Інтерфейс, коментар, титры і подякы у 8 языках.","tags":["Voyager","документ"]},"EXIF-CURAT":{"line":"Робота ся проваджать: інштрумент на перегляд і выдаляня скрытых даных у файлах (образы, PDF, Office, відео: EXIF, GPS, XMP), з парсерами безпечныма для пам'яті, написаный в Rust. Доселя лем пре-альфа скелет.","detail":"Робота в проґресі: інштрумент на показ і выдаліня схованых дат у файлах (образы, PDF, Office, відео: EXIF, GPS, XMP), з парсерами безпечными для памяти, написаный на Rust. Поки лем скелет pre-alpha.","tags":["метадані","приватность"]},"PORUMBEL":{"line":"Автоматічно переносить фото, зроблены з Open Camera на телефоні, до папкы на компютері, єдна папка на сесію, і отвірать їх в LegatorOCR. Без конта, без хмары, без crate третіх сторін.","detail":"Мала програма, написана на Rust, без крейтів третіх сторін (Windows, macOS, Linux), котра переносить на ваш компютер фото, зроблены в Open Camera: через Wi-Fi (сторінка загрузкы або WebDAV, з QR-кодом), через ADB (USB або Wi-Fi) або з синхронізованой папкы (Syncthing і т. п.). Складає фото до єдной папкы на сесію зніманя і отвераєт кажду готову сесію в LegatorOCR (ділїня, выправліня нахылу, обтинаня, PDF з OCR). Локална контролна панель і команда «porumbel doctor» на діаґнозу; ничого не выходить з вашой мережі. Версія 0.x; ліценція MIT.","tags":["фото","переношіня"]},"colibri-companion":{"line":"Приязный десктопный додаток для colibri, локалного двигуна інференції: выберте модель, котра пасує до вашого компютера, стягніте єдным клікнутєм і балакайте з ньом. Без конта, без хмарового сервісу.","detail":"Десктопна програма, написана на Rust, до colibri (JustVugg/colibri): знаходить Python і colibri, показує лем моделі, котры влізуть до памяти вашого компютера, стягує їх з паузов і продовжіньом, запускать локалный сервер і отвераєт чат (одповіді в потоці, Markdown, збереженé розговоры, пошук, локалны документы і інштрументы MCP з потвердженём каждого воланя). Панель Resources показує процесор, память, ґрафічну карту і отверены споїня. Windows, macOS, Linux; інтерфейс у 8 языках; ліценція Apache-2.0.","tags":["локалный ШІ","десктоп"]},"CartaColibri":{"line":"Локална бібліотека ШІ на двигуні Colibrì: індексує папкы, котры выберете, шукать в них блыскавічно і просить локалну модель зробити резюме, выдобыти дані або синтезу, все з указаньом файлу-жерела. Ничого не опущать ваш компютер.","detail":"Програма на Rust, з локалнов сторінков (127.0.0.1) і командным рядком. Індексує папкы, котры выберете (орігіналы лем чітає, ниґда не міняє), шукать по цілім тексті (слова, «фразы», префікс*, AND/OR/NOT, фільтры по тіпу, розмірі, місцю) і ґрупує файлы. Локална модель Colibrì робить резюме, выберать (табліцю або JSON, «NOT FOUND» замість здогадів), сінтезує або порівнює, все з цітованыма жерелами [S1], [S2] і оцінков заземліня. Має также малый браузер web-grab, MCP-сервер лем до чітаня, імпорты (закладкы, Obsidian, Zotero, RSS) і перевірку властного тексту проти бібліотекы. Без конта, без телеметрії; інтерфейс у 8 языках; alpha-версія 0.2; ліценція MIT.","tags":["локалный ШІ","бібліотека"]},"PolyTabletop":{"line":"240 настольных ґр, в котры можете грати проти компютера, в терміналі або в ґрафічнім вікні, плюс ґра на двох при єднім компютері або по мережі. Написаны в Rust; двигун і ґры не мають зовнішніх залежностей.","detail":"Clean-room колекція настолных ґор, написана на Rust: 240 ґор, в котры ся дасть ґрати проти компютера, в терміналі або в ґрафічнім вікнї, плюс hot-seat і мережева ґра на двох. Абстрактны класікы, карточны і костяны ґры, орігіналны варіанты сучасных механік під властныма назвами, кооператівны ґры з партнером-ШІ, ґры зо схованыма ролями, ґры на забаву і словны ґры; каталоґ має 1200 записів, з набором для рольовых ґор (кости, листкы, ґенератор підземель, симулатор боёв). Суперник-ШІ (alpha-beta, MCTS), арена ШІ проти ШІ, транскрипты і повторы. Інтерфейс у 8 языках; версія 0.9; ліценція MIT або Apache-2.0.","tags":["настольны ґры","Rust"]},"STRAJA":{"line":"Щыт проти аґентів ШІ, што чітають ваш телефон: показує, котры додаткы можуть чітати ваши сповіщіня, екран, фото і SMS, варує, коли новый достане доступ, і проведе вас до налаштованя, де го одкличете. Без конта, без дозволу INTERNET.","detail":"Додаток для Android (APK) і iPhone (непідписаный IPA). На Android выписує додатки з доступом до сповіщінь, службами доступности, ролёв асістента і дозволами на медії і SMS, з оцінков ризіка на додаток і на цілый телефон; періодічный монітор порівнює телефон з основнов лініёв і сповіщає вас про каждый новый доступ. Отвераєт точну сторінку сістемных настройок на одкліканя доступу і ниґда ничого не міняє потайкы. Тимчасовый доступ з наганяньом і порадник защіты з 12 пунктів. На iPhone аудіту нема (iOS ховать дозволы іншых додатків), є лем порадник, ручный реєстр і нагадованя. Не годен затримати аґента. Без дозволу INTERNET, без резервной копії; 8 языків; версія 1.0; ліценція MIT.","tags":["приватность","телефон"]},"CUPLAJ":{"line":"Партійна телефонія для імерсівного театру: флота звычайных телефонів Android стає приватнов телефоновов централєв по Wi-Fi місця, без хмары, без контів, без реклам. Її основна функція є «cuplaj»: спільна партійна лінія стацыонарных телефонів од 1980-ых до приблизно 2006.","detail":"Додаток для Android (APK) і для iPhone/iPad (непідписаный IPA). Орґанізаторы і актори говорять зо ґлядачами через локалне Wi-Fi; єден телефон (контрольный) є централа. Шість телефонных епох (1985 дісковый, 1995 клавішный, 2003 мобілный, 2025 смартфон, 2045 носимы пристрої, 2080 спільный розум), спільна лінія, де два абоненты ділять єдну лінію, справжні воланя, публічне оголошіня по натисканю, канал за кулісами, сіґналы (текст на цілый екран, вібрація, дзвінок, спалах, ґоворена мова, фантомне воланя) і сценарій з GO і PLAY. Без інфраструктуры, на выбір мережевый ключ AES-128-GCM, пряме воланя P2P. Без аналітікы, без серверів, без конт. 8 языків; версія 1.10; ліценція MIT.","tags":["імерсівный театр","телефонія"]},"LUSTRUM":{"line":"Верните свій телефон собі: находить смітя, дублікаты, подібны фото і остаткы по додатках і чістить їх лем з вашом згодов. Не мать дозволу INTERNET, тому фізічно не може ничого нікуда послати.","detail":"Додаток для Android (Kotlin). Сховище по тіпах файлів, великы, стары і смітевы файлы, точны дублікаты (розмір, швыдкый відбиток, потім SHA-256), подобны фото (перцептівне хешованя), остатки по выдаленых додатках, стискання JPEG, кеші, розмазаны і темны фото, Swiper (вліво = выдалити, вправо = зоставити), планованé чістіня і 30-деннный кошик LUSTRUM на скасованя. Без дозволу INTERNET: ничого не выходить з телефона. Без чудес на рівні root: Android 11+ не пущає ніякый звычайный додаток до папок даных іншых додатків. 8 языків (машинны переклады); бета-версія 0.8; ліценція MIT.","tags":["чістячій телефон","Android"]},"STENOGRAMA":{"line":"Транскрипція довгого аудіа просто в переглядачі, з локалным Whisper: єден файл HTML, без конта, без сервера, без водяного знаку. Ваш аудіофайл ніколи не опущать пристрій; лем модель Whisper ся стягує, раз.","detail":"Чітає MP3 і WAV кусками (тому довжіна не є обмежена памятёв); іншы формата (M4A, OGG/Opus, MP4, FLAC) ся декодують цілы. Каждый кусок ся рже в паузі, жебы слова не ділили ся; поступ ся зберігать, тому можете перерваты і продовжіти. Редактор на сторінці (клікніть час, жебы почути місце), выдаліня типовых «фантомных» фраз Whisper, експорт до .txt, .srt, .vtt, .docx або до буфера. Ужывать WebGPU, коли є, інакше процесор (WASM). Інсталовална PWA; модель остає в кеші по першім стягненю. Бібліотека ся загружать з jsDelivr при першім переписованю, перевіряна SHA-384. Інтерфейс у 7 языках; ліценція MIT.","tags":["транскрипція","аудіо"]},"GERMEN":{"line":"Навчте малу языкову модель од нулы, в чістым Rust, на звычайнім ЦП: без Python, без CUDA, без конта, без доступу до мережі, без телеметрії. Єден бінарник, єден текстовый файл, єдна команда.","detail":"Програма на Rust (на Burn, з єго чісто-Rust CPU-бекендом), котра тренує мережу стілю GPT над байтами або над словником BPE, выученым з вашого властного тексту, потім ґенерує текст з тренованой моделі. GERMEN Studio: локалне вікно (127.0.0.1) з кривков страты, швыдкостёв і зразками тексту, у 8 языках. Команды на мірїня швыдкости вашого компютера і на перевірку і справу файлів моделі. Є майстерня на навчаня і експерименты, не фабрика чат-ботів: модель з 1–25 мілёнів параметрів вчіть ся форму тексту, не знаня о світі. Без GPU, без мішаной точности. Версія 0.6; ліценція MIT.","tags":["локалный ШІ","Rust"]},"CUANTOR":{"line":"Сімулятор квантового компютера для вашого десктопа, од 5 до 1000 кубітів, з інтерфейсом в стилю IBM Quantum Composer. Точна математіка, але не справжнє квантове залізо.","detail":"Програма на Rust зо чотырёх частей (ядро, вікно, командный рядок, звязок з IBM) для Windows, macOS і Linux. Дошка на малюваня як Composer од IBM: ставте цветны брамы на лініях (кубіты) і дывте ся, як стовпцы і сфера показують результат, док текстова панель пише тот самый схемат наживо в OpenQASM і Qiskit. Три калькуляторы: єден, котрый памятать каждé чісло (до 28 кубітів), єден дуже швыдкый на простых брамах (до 4096) і єден на схемы з малов кількостёв розвітвлінь. Вимір, ресет і if посеред выконаня, властны брамы, симулованый шум, результаты, котры можете повторити зо зерном. Чітає OpenQASM 2.0 і 3.0; схемат можете отворити в IBM Composer або послати на справжню машіну IBM з ключом вашого конта (не перевіреное на справжнім залізі IBM). Інтерфейс у 8 языках; версія 0.2.","tags":["квантовый компютер","сімулятор"]}});
